            padding: 15px 25px;
            margin-bottom: 30px;
            font-size: 1.1em;
            border-radius: 0 8px 8px 0;
            box-shadow: 2px 2px 10px var(--shadow-color);
        }

        /* 通用标题样式 */
        h2 {
            color: var(--primary-accent-color);
            border-bottom: 2px solid #f3e5f5;
            /* 使用淡紫色作为分隔线 */
            padding-bottom: 10px;
            margin-top: 20px;
            font-weight: 700;
        }

        /* 内心独白区域 */
        .psychology-section {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .thought-bubble {
            background-color: var(--card-bg-color);
            border: 1px solid var(--border-color);
            padding: 20px;
            border-radius: 12px;
            box-shadow: 3px 3px 15px var(--shadow-color);
            position: relative;
        }

        .thought-bubble h3 {
            margin-top: 0;
            color: var(--secondary-accent-color);
            font-weight: 400;
            display: flex;
            justify-content: space-between;
        }

        .thought-bubble p {
            white-space: pre-wrap;
            /* 保留换行符 */
            font-size: 1.1em;
        }

        /* 状态盒子 */
        .status-box {
            background-color: var(--card-bg-color);
            padding: 20px;
            border-radius: 12px;
            box-shadow: 3px 3px 15px var(--shadow-color);
            border: 1px solid var(--border-color);
        }

        .stat-value {
            line-height: 1.5;
        }

        .progress-bar-container {
            width: 100%;
            background-color: #ffe9f1;
            border-radius: 5px;
            height: 20px;
            overflow: hidden;
            display: flex;
            align-items: center;
            position: relative;
        }

        .progress-bar-fill {
            height: 100%;
            border-radius: 5px 0 0 5px;
            transition: width 0.5s ease-in-out;
            background-color: #e74c3c;
        }

        .progress-bar-text {
            position: absolute;
            left: 10px;
            color: white;
            font-size: 0.8em;
            font-weight: bold;
            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
        }

        .game-time {
            text-align: center;
            font-size: 1.2em;
            font-weight: bold;
            color: var(--secondary-accent-color);
            margin-bottom: 25px;
            padding: 10px;
            background-color: #f3e5f5;
            /* 淡紫色背景 */
            border-radius: 8px;
        }

        .card-container {
            display: grid;
            gap: 20px;
        }

        .character-card {
            background-color: var(--bg-color);
            border: 1px solid var(--border-color);
            border-radius: 10px;
            padding: 15px 20px;
            transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
        }

        .character-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 8px 20px rgba(123, 31, 162, 0.15);
            /* 悬浮时阴影加深 */
        }

        .character-card h3 {
            margin-top: 0;
            margin-bottom: 15px;
            color: var(--primary-accent-color);
            font-weight: 700;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .personality-tag {
            font-size: 0.7em;
            font-weight: bold;
            color: white;
            background-color: var(--secondary-accent-color);
            /* 使用深紫色标签背景 */
            padding: 3px 8px;
            border-radius: 10px;
        }

        .card-item {
            display: flex;
            align-items: flex-start;
            margin-bottom: 10px;
            font-size: 1.1em;
        }

        .card-item strong {
            flex-shrink: 0;
            width: 70px;
            /* 固定标签宽度 */
            color: var(--text-color);
            font-weight: 400;
        }

        .card-item span {
            flex-grow: 1;
        }

        .quoted {
            color: orange;
        }

        .thought {
            color: red;
        }
    </style>
</head>

