    <script>
        // 原始JSON数据
        // 您的JSON字符串
        const jsonString = `{{match}}`;

        // 解析JSON
        const jsonData = JSON.parse(jsonString);


        // Emoji 映射表
        const emojiMap = {
            xiayuchan: '💘',
            suwanqing: '💝',
            player: '',
            action: '🏃‍♀️',
