            anal: '🌼',
            breast: '🥥',
            uterus: '💗',
            penis: '🔥'
        };

        // 用于将JSON键名翻译成中文的辅助函数
        function translateKey(key) {
            const translations = {
                action: '动作',
                pose: '姿势',
                clothes: '穿着',
                mouth: '口腔',
                pussy: '小穴',
                anal: '肛门',
                breast: '胸部',
                uterus: '子宫',
                penis: '阴茎'
            };
            return translations[key] || key;
        }

        // 页面加载完成后执行
        document.addEventListener('DOMContentLoaded', () => {
            // 1. 渲染场景描述
            let roleplayHtml = '';
            const roleplayLines = jsonData.roleplay.split('\n');
            roleplayLines.forEach(line => {
                let processedLine = line
                    .replace(/(".*?")/g, '<span class="quoted">$&</span>')
                    .replace(/(「.*?」)/g, '<span class="quoted">$&</span>')
                    .replace(/(“.*?”)/g, '<span class="quoted">$&</span>')
                    .replace(/(【.*?】)/g, '<span class="thought">$&</span>');
                roleplayHtml += `${processedLine}<br>`;
            });
            const sceneContainer = document.getElementById('roleplay-scene');
            sceneContainer.innerHTML = `<div class="scene-description">${roleplayHtml}</div>`;

            // 2. 渲染内心独白
            const thoughtsContainer = document.getElementById('character-thoughts');
            for (const character in jsonData.spirit) {
                const thoughtData = jsonData.spirit[character];
