                    let characterName = character === 'xiayuchan' ? '夏语蝉' : '苏婉晴';
                    let thoughtHtml = '';
                    const thoughtLines = thoughtData.psychology.split('\n');
                    thoughtLines.forEach(line => {
                        let processedLine = line
                            .replace(/(".*?")/g, '<span class="quoted">$&</span>')
                            .replace(/(「.*?」)/g, '<span class="quoted">$&</span>')
                            .replace(/(“.*?”)/g, '<span class="quoted">$&</span>')
                            .replace(/(【.*?】)/g, '<span class="thought">$&</span>');
                        thoughtHtml += `${processedLine}<br>`;
                    });
                    const sceneContainer = document.getElementById('roleplay-scene');
                    sceneContainer.innerHTML = `<div class="scene-description">${roleplayHtml}</div>`;
                    thoughtsContainer.innerHTML += `
                        <div class="thought-bubble">
                            <h3><span>${emojiMap[character] || '🤔'} ${characterName} 的想法...</span>
                            ${characterName === '夏语蝉' ? '' : `<span class="personality-tag">意识位置:${thoughtData.state == 'In testicles' ? '🥚睾丸中' : thoughtData.state == 'In semen' ? `💦精液中(剩余${thoughtData.restTime})` : `💃原身体中(剩余${thoughtData.restTime})`}</span>`}</h3>
