                                    <div class="progress-bar-fill" style="width: ${thoughtData.climax}%;"></div>
                                </div>
                            </div>
                            <div class="stat-label">💢 欲求值</div>
                            <div class="stat-value">
                                <div class="progress-bar-container">
                                    <div class="progress-bar-text">${thoughtData.desire} / 100</div>
                                    <div class="progress-bar-fill" style="width: ${thoughtData.desire}%;"></div>
                                </div>
                            </div>
                            ${characterName === '苏婉晴' ? `<div class="stat-label">💓 接受度</div>
                    <div class="stat-value">
                        <div class="progress-bar-container">
                             <div class="progress-bar-text">${thoughtData.acceptability} / 100</div>
                            <div class="progress-bar-fill" style="width: ${thoughtData.acceptability}%;"></div>
                        </div>
                    </div>`: '<br><br>'}
                            <br>
                            <p>${thoughtHtml}</p>
                        </div>
                    `;
                }
            }

            // 3. 渲染游戏状态
            const timeContainer = document.getElementById('game-time-display');
            timeContainer.innerHTML = `<div class="game-time">🕒 ${jsonData.statusBox.time}</div>`;

            // 4. 渲染角色状态卡片
            const statusContainer = document.getElementById('character-status');
            const bodies = jsonData.statusBox.bodys;

            for (const characterKey in bodies) {
                if (characterKey == 'player') continue
                const data = bodies[characterKey];
                let cardHTML = '';

                // 设置卡片标题和Emoji
                let characterName = '';
                switch (characterKey) {
                    case 'xiayuchan': characterName = '夏语蝉'; break;
                    case 'suwanqing': characterName = '苏婉晴'; break;
                    case 'player': characterName = '你'; break;
                }

                cardHTML += `
                    <div class="character-card">
                        <h3>
                            <span>${emojiMap[characterKey] || '👤'} ${characterName}</span>
                            ${data.personality ? `<span class="personality-tag">人格: ${data.personality}</span>` : ''}
                        </h3>
                `;

                // 遍历角色的所有属性
                for (const itemKey in data) {
                    // 过滤掉无用信息和人格标签
                    const value = data[itemKey];
                    if (itemKey !== 'personality') {
                        cardHTML += `
                            <div class="card-item">
                                <strong>${emojiMap[itemKey] || '✨'} ${translateKey(itemKey)}:</strong>
                                <span>${value}</span>
                            </div>
                        `;
                    }
                }
                cardHTML += '</div>';
                statusContainer.innerHTML += cardHTML;
            }
        });
    </script>
</body>

</html>
